//! IPC surface: error type, bridge DTOs, events, raw streaming, specta builder.

pub mod dto;
pub mod error;
pub mod events;
pub mod stream;

pub use error::{ApiError, ApiResult};

use specta_typescript::Typescript;
use tauri_specta::{collect_commands, collect_events, Builder, ErrorHandlingMode};

use crate::commands::{app, catalog, identity, probe, session, sftp, stats, tree, vault};

/// Commands NOT generated by tauri-specta (raw request body, see ADR-004). The UI calls them
/// through hand-written wrappers in `ui/src/lib/api/raw.ts`.
pub const RAW_COMMANDS: &[&str] = &["shell_write"];

/// Commands that do NOT count as user activity for the backend auto-lock (ADR-007):
/// they are triggered by server output or by the app itself, not by the user.
pub const PASSIVE_COMMANDS: &[&str] = &[
    "shell_ack",
    "vault_status",
    "transfers_subscribe",
    "stats_sample",
    "host_probe",
];

/// The tauri-specta builder with every typed command and event of `docs/contracts/ipc.md`.
#[must_use]
pub fn builder() -> Builder<tauri::Wry> {
    Builder::<tauri::Wry>::new()
        .error_handling(ErrorHandlingMode::Result)
        .disable_serde_phases()
        // i64 unix millis and u64 byte sizes stay < 2^53 (ADR-004).
        .dangerously_cast_bigints_to_number()
        .commands(collect_commands![
            tree::tree_list,
            tree::folder_create,
            tree::folder_update,
            tree::folder_move,
            tree::folder_delete,
            tree::host_create,
            tree::host_update,
            tree::host_duplicate,
            tree::host_delete,
            tree::host_move,
            tree::host_resolve,
            tree::host_search,
            identity::identity_list,
            identity::identity_create,
            identity::identity_update,
            identity::identity_delete,
            identity::identity_import_file,
            catalog::tag_list,
            catalog::tag_create,
            catalog::tag_update,
            catalog::tag_delete,
            catalog::snippet_list,
            catalog::snippet_create,
            catalog::snippet_update,
            catalog::snippet_delete,
            catalog::forward_list,
            catalog::forward_create,
            catalog::forward_update,
            catalog::forward_delete,
            catalog::known_host_list,
            catalog::known_host_delete,
            catalog::settings_get,
            catalog::settings_set,
            vault::vault_status,
            vault::vault_init,
            vault::vault_unlock,
            vault::vault_lock,
            vault::vault_change_password,
            vault::vault_export,
            vault::vault_import,
            session::session_open,
            session::session_open_adhoc,
            session::shell_ack,
            session::shell_resize,
            session::session_close,
            session::session_reconnect,
            session::hostkey_accept,
            session::kbd_interactive_reply,
            session::passphrase_reply,
            sftp::sftp_open,
            sftp::sftp_close,
            sftp::sftp_list,
            sftp::sftp_stat,
            sftp::sftp_mkdir,
            sftp::sftp_rename,
            sftp::sftp_remove,
            sftp::sftp_chmod,
            sftp::sftp_realpath,
            sftp::local_home,
            sftp::local_list,
            sftp::local_mkdir,
            sftp::local_rename,
            sftp::local_remove,
            sftp::transfer_enqueue,
            sftp::transfer_pause,
            sftp::transfer_resume,
            sftp::transfer_cancel,
            sftp::transfer_retry,
            sftp::transfer_conflict_reply,
            sftp::transfers_subscribe,
            stats::stats_sample,
            probe::host_probe,
            app::app_info,
            app::open_external,
        ])
        .events(collect_events![
            events::VaultLocked,
            events::TreeChanged,
            events::UpdateAvailable
        ])
}

/// Writes the TypeScript bindings to `path` (used by `just bindings` and the freshness test).
pub fn export_bindings(path: &std::path::Path) -> Result<(), String> {
    builder()
        .export(
            Typescript::default()
                .header("/* eslint-disable */\n// GENERATED by `just bindings` — do not edit.\n"),
            path,
        )
        .map_err(|e| e.to_string())
}
